from author_tools import *

def R89(text):
    """Decode individually authored records; no expansion of task templates."""
    import ast
    out=[]
    for row in text.strip().splitlines():
        key,prompt,a,solution,oracle,diff=row.split('|')
        raw,_,display=a.partition('~')
        if '/' in raw and not raw.startswith('['): value=float(F(raw))
        else: value=ast.literal_eval(raw)
        answer=(value,display or ('; '.join(map(str,value)) if isinstance(value,list) else raw))
        out.append(('8-'+key,prompt,answer,solution,oracle,diff))
    return out

